from collections import deque

sys.setrecursionlimit(10000)
toks = sys.stdin.read().split()

def build():
    if toks[0] == 'null':
        return None
    root = [int(toks[0]), None, None]
    q = deque([root])
    i = 1
    while q and i < len(toks):
        node = q.popleft()
        for side in (1, 2):
            if i < len(toks):
                if toks[i] != 'null':
                    node[side] = [int(toks[i]), None, None]
                    q.append(node[side])
                i += 1
    return root

def depth(node):
    if node is None:
        return 0
    return 1 + max(depth(node[1]), depth(node[2]))

print(depth(build()))

